 if (step_arr[i] == 0) { 
 break; 
 } 
 i++; 
 } 

 climb(step_arr, reachable); 

 printf("\nStep numbers traversed from the ground level are: \n"); 
 for (j = 0; reachable[j] != 0; j++) { 

 printf("%d ", j); 
 } 

 return 0; 
}

